-- =============================================================================
-- V176 — OCCPL's pincode master sheet (Pincode_Master_NEW_DT_15-4-2024), stored exactly as given (user, 2026-11-25)
--
-- One row per sheet row (19168 rows, in sheet order; row_no is the Excel row number), every cell as Excel shows it:
-- text as written, whole numbers without decimals, TRUE / FALSE for the boolean cells, #N/A for the error cells,
-- NULL for an empty cell. International rows and duplicate pincodes are kept, nothing is cleaned or skipped.
-- Read through GET /api/v1/global-masters/pincode-sheet. Generated, do not edit.
-- =============================================================================

CREATE TABLE pincode_master_sheet (
    row_no            INT          NOT NULL,
    pincode           VARCHAR(20)  NULL,
    city              VARCHAR(150) NULL,
    state             VARCHAR(100) NULL,
    region            VARCHAR(50)  NULL,
    zone              VARCHAR(50)  NULL,
    doc_is_oda        VARCHAR(10)  NULL,
    doc_serv          VARCHAR(20)  NULL,
    doc_tat           VARCHAR(20)  NULL,
    surface_serv      VARCHAR(20)  NULL,
    surface_tat       VARCHAR(20)  NULL,
    air_service       VARCHAR(20)  NULL,
    air_tat           VARCHAR(20)  NULL,
    PRIMARY KEY (row_no),
    KEY idx_pms_pincode (pincode),
    KEY idx_pms_region (region),
    KEY idx_pms_zone (zone)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci
  COMMENT = 'OCCPL pincode master sheet, verbatim (V176)';

